// Rounded, outlined music stickers. All artwork stays crisp on tablets.
const wrap=body=>`<svg viewBox="0 0 64 64" fill="none" stroke="#34324b" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" xmlns="http://www.w3.org/2000/svg">${body}</svg>`;
const spark='<path d="m52 7 1.8 4.2L58 13l-4.2 1.8L52 19l-1.8-4.2L46 13l4.2-1.8Z" fill="#ffda77" stroke-width="2.2"/>';
export const STICKERS={
  piano:wrap('<rect x="7" y="14" width="50" height="37" rx="9" fill="#cab9f6"/><rect x="11" y="27" width="42" height="20" rx="4" fill="#fffdf8"/><path d="M21 28v18m11-18v18m11-18v18"/><path d="M18 28v8m12-8v8m12-8v8" stroke-width="6"/><path d="M17 21h12m7 0h2" stroke="#fffdf8"/>'),
  electronic:wrap('<rect x="7" y="16" width="50" height="36" rx="12" fill="#9adbd5"/><path d="m28 9-9 21h12l-4 15 20-25H34l7-11Z" fill="#ffe081"/><circle cx="17" cy="43" r="3" fill="#ef83a2"/><path d="M46 43h2"/>'),
  maracas:wrap('<g transform="rotate(-27 23 31)"><rect x="19" y="29" width="9" height="28" rx="4.5" fill="#ffdc83"/><ellipse cx="23.5" cy="23" rx="13" ry="17" fill="#f78faa"/><path d="M12 19h23m-22 9h21" stroke="#fff8eb"/><circle cx="23" cy="11" r="2" fill="#fff8eb" stroke="none"/></g><g transform="rotate(28 44 33)"><rect x="40" y="31" width="8" height="25" rx="4" fill="#ffdc83"/><ellipse cx="44" cy="25" rx="11" ry="14" fill="#9adbd5"/><path d="M35 25h18" stroke="#fff8eb"/></g>'),
  xylophone:wrap('<path d="m16 17-5 34m39-32 4 32"/><rect x="7" y="12" width="11" height="30" rx="4" fill="#75bfe6"/><rect x="17" y="15" width="11" height="28" rx="4" fill="#ee99bb"/><rect x="27" y="19" width="11" height="25" rx="4" fill="#ffda77"/><rect x="37" y="23" width="11" height="22" rx="4" fill="#f38a95"/><rect x="47" y="26" width="11" height="19" rx="4" fill="#8dd5bc"/><path d="m17 57 16-23m12 23L30 37" stroke-width="5"/><circle cx="34" cy="31" r="6" fill="#fff7ea"/><circle cx="28" cy="34" r="6" fill="#fff7ea"/>'),
  bell:wrap('<path d="M28 11a5 5 0 0 1 10 0v4H28Z" fill="#c7b6f4"/><path d="M17 29c0-21 30-21 30 0v10l6 6H11l6-6Z" fill="#ffda77"/><path d="M27 46a6 6 0 0 0 12 0" fill="#ed9a81"/><path d="M24 28c0-5 2-8 5-9" stroke="#fff9e9" stroke-width="4"/>'+spark),
  drum:wrap('<path d="M10 28v21c0 13 44 13 44 0V28" fill="#f390a3"/><path d="m11 32 8 18 9-17 9 18 8-18 8 17" fill="#ffda77"/><ellipse cx="32" cy="28" rx="22" ry="9" fill="#fff9eb"/><path d="M10 50c10 8 34 8 44 0"/><path d="m14 7 20 22M50 7 29 29" stroke="#ffdc83" stroke-width="6"/><path d="m14 7 20 22M50 7 29 29" stroke-width="2.5"/>'),
  mic:wrap('<g transform="rotate(34 32 32)"><rect x="25" y="22" width="14" height="35" rx="6" fill="#9adbd5"/><rect x="19" y="6" width="26" height="29" rx="13" fill="#c8b9ed"/><path d="m20 15 24 11m-23-3 17 8"/><path d="M31 43v5" stroke="#fffdf8" stroke-width="4"/></g>'+spark),
  music:wrap('<path d="M26 44V14l25-5v29M26 24l25-5" fill="#f6a2ba"/><ellipse cx="17" cy="46" rx="9" ry="7" fill="#c8b5ef"/><ellipse cx="42" cy="40" rx="9" ry="7" fill="#8ed6c5"/><path d="m9 12 2 4 4 2-4 2-2 4-2-4-4-2 4-2Z" fill="#ffda77" stroke-width="2"/>'),
  pencil:wrap('<path d="m14 38 27-28c3-3 15 9 12 12L26 50l-16 5Z" fill="#ffdc83"/><path d="m36 15 12 12m-8-16 12 12" fill="#f8a1bb"/><path d="m14 38 12 12m-16 5 3-10 7 7Z" fill="#cab9f2"/><path d="m20 37 20-20" stroke="#fffaf0" stroke-width="3"/>'+spark),
  play:wrap('<rect x="7" y="7" width="50" height="50" rx="19" fill="#b9e8d8"/><path d="m26 20 18 12-18 12Z" fill="#fffaf0"/>'),
  stop:wrap('<rect x="7" y="7" width="50" height="50" rx="19" fill="#f8b6c8"/><rect x="22" y="22" width="20" height="20" rx="5" fill="#fffaf0"/>'),
  video:wrap('<rect x="6" y="13" width="40" height="38" rx="11" fill="#cab9f2"/><path d="m46 25 12-7v28l-12-7Z" fill="#92d6c8"/><path d="m22 24 12 8-12 8Z" fill="#fff9eb"/>'+spark),
  download:wrap('<path d="M11 39v10a7 7 0 0 0 7 7h28a7 7 0 0 0 7-7V39" fill="#b9e8d8"/><path d="M32 7v33m-13-13 13 13 13-13" stroke="#34324b" stroke-width="5"/><path d="M32 8v28m-10-8 10 10 10-10" stroke="#f4afc7" stroke-width="3"/>'),
  arrow:wrap('<rect x="6" y="11" width="52" height="42" rx="20" fill="#ffdc83"/><path d="M18 32h27M34 22l11 10-11 10"/>'),
  expand:wrap('<rect x="8" y="9" width="48" height="46" rx="13" fill="#c1e6ec"/><path d="M26 19h-9v9m21-9h9v9M17 37v9h9m21-9v9h-9"/>'),
  help:wrap('<path d="M15 51 6 57l3-17C-2 12 21 2 37 7c27 7 27 42-3 46Z" fill="#ffdc83"/><path d="M25 24c0-10 16-11 16-1 0 6-8 6-8 13"/><circle cx="33" cy="43" r="1.8" fill="#34324b" stroke="none"/>')
};
export function sticker(id,cls=''){return `<span class="music-sticker ${cls}" aria-hidden="true">${STICKERS[id]||STICKERS.music}</span>`;}
